export function planDependencies(records,requestedIds) {
  if(!Array.isArray(requestedIds) || requestedIds.some(id=>typeof id!=='string')) throw Error('invalid requested ids');
  const nodes=new Map(records.map(r=>[r.id,r])), done=new Set(), active=new Set(), path=[], result=[];
  function visit(id) {
    if(!nodes.has(id)) throw Error('missing id: '+id);
    if(active.has(id)) throw Error('cycle: '+[...path.slice(path.indexOf(id)),id].join(' -> '));
    if(done.has(id)) return;
    active.add(id);path.push(id);
    for(const dep of nodes.get(id).dependencies) visit(dep);
    path.pop();active.delete(id);done.add(id);result.push(id);
  }
  for(const id of requestedIds) visit(id);
  return result;
}
export function reverseDependencies(records,id) {
  if(!records.some(r=>r.id===id)) throw Error('unknown id: '+id);
  const reverse=new Map();
  for(const r of records) for(const dep of r.dependencies) {if(!reverse.has(dep)) reverse.set(dep,[]); reverse.get(dep).push(r.id);}
  const seen=new Set([id]), stack=[id];
  while(stack.length) for(const parent of reverse.get(stack.pop())??[]) if(!seen.has(parent)) {seen.add(parent);stack.push(parent);}
  seen.delete(id);return [...seen].sort();
}

src/search.mjs.text:
import {parseVersion,compareVersions} from './version.mjs';
const cmp=(a,b)=>a<b?-1:a>b?1:0;
export function searchRecords(records,query={}) {
  if(!query || typeof query !== 'object' || Array.isArray(query)) throw Error('invalid query');
  const {text='',tags=[],sortBy='id',order='asc',offset=0,limit=20,versionMin,versionMax}=query;
  if(typeof text !== 'string' || !Array.isArray(tags) || tags.some(t=>typeof t!=='string')) throw Error('invalid text/tags');
  if(!['id','name','version'].includes(sortBy) || !['asc','desc'].includes(order) || !Number.isInteger(offset) || offset<0 || !Number.isInteger(limit) || limit<1 || limit>100) throw Error('invalid sort/order/paging');
  if(versionMin!==undefined) parseVersion(versionMin);
  if(versionMax!==undefined) parseVersion(versionMax);
  const needle=text.trim().toLowerCase(), required=[...new Set(tags.map(t=>t.trim().toLowerCase()).filter(Boolean))];
  const items=records.filter(r=>(r.id.toLowerCase().includes(needle)||r.name.toLowerCase().includes(needle)) && required.every(t=>r.tags.map(x=>x.trim().toLowerCase()).includes(t)) && (versionMin===undefined || compareVersions(r.version,versionMin)>=0) && (versionMax===undefined || compareVersions(r.version,versionMax)<=0));
  items.sort((a,b)=>((sortBy==='version'?compareVersions(a.version,b.version):cmp(a[sortBy],b[sortBy]))*(order==='asc'?1:-1)) || cmp(a.id,b.id));
  return {items:items.slice(offset,offset+limit).map(r=>({...r,tags:[...r.tags],dependencies:[...r.dependencies]})),total:items.length,offset,limit};
}

